// Блок «תזכורות מהירות» на /home: чтение строк и открытие главной в подменённое время (#3cc72778).
//
// Как работает приложение: при открытии /home вызывается RPC generate_reminders({p_day, p_in_israel}) —
// сервер пишет строки напоминаний на еврейский день p_day (после שקיעה — уже следующий день) и удаляет строки других дней
// (фикс c695450), затем блок перечитывается. Поэтому порядок дат в тестах любой, но после подмены часов
// нужно один раз открыть /home на реальном времени в НОВОМ контексте (restoreTodayReminders) — иначе в аккаунте
// до следующего входа лежат напоминания подменённого дня.
import { Browser, BrowserContextOptions, expect, Page, TestInfo } from '@playwright/test';
import * as path from 'path';
import { setFixedTimeKeepingSession } from './clock';

export const TEFILLIN_TITLE = 'הנחת תפילין';
export const TEFILLIN_TEXT = 'אל תשכח להניח היום עד השקיעה';

export type ReminderRow = { title: string; sub: string; lines: number; iconRight: boolean | null; overflow: boolean };

/** Строки блока «תזכורות מהירות» (без заголовка); ждёт, пока список перестанет меняться. */
export async function readReminders(page: Page): Promise<ReminderRow[]> {
  const title = page.getByText('תזכורות מהירות', { exact: true });
  await expect(title).toBeVisible({ timeout: 25_000 });
  const snap = () =>
    title.evaluate((t) => {
      const block = t.parentElement!.parentElement!;
      return [...block.children].slice(1).map((r) => {
        const lines = (r as HTMLElement).innerText.split('\n').map((s) => s.trim()).filter(Boolean);
        // кружок иконки: квадратный элемент 24–72 px со скруглением ≥ половины стороны и svg/img внутри
        const circle = [...r.querySelectorAll('div')].find((d) => {
          const b = d.getBoundingClientRect();
          const cs = getComputedStyle(d);
          return b.width >= 24 && b.width <= 72 && Math.abs(b.width - b.height) < 2 && parseFloat(cs.borderTopLeftRadius) >= b.width / 2 - 1 && !!d.querySelector('svg,img');
        });
        const firstText = [...r.querySelectorAll('div,span')].find((e) => e.childElementCount === 0 && (e.textContent ?? '').trim());
        const ib = circle?.getBoundingClientRect();
        const tb = firstText?.getBoundingClientRect();
        return {
          title: lines[0] ?? '',
          sub: lines[1] ?? '',
          lines: lines.length,
          iconRight: ib && tb ? ib.left >= tb.right - 1 : null,
          overflow: r.scrollWidth > r.clientWidth + 1,
        };
      });
    });
  // список стабилен: два одинаковых снимка подряд, в каждой строке есть текст
  let prev = '';
  let rows: ReminderRow[] = [];
  await expect
    .poll(
      async () => {
        rows = await snap();
        const cur = JSON.stringify(rows.map((r) => [r.title, r.sub]));
        const stable = rows.length > 0 && rows.every((r) => r.title) && cur === prev;
        prev = cur;
        return stable;
      },
      { timeout: 25_000, intervals: [700] },
    )
    .toBe(true);
  return rows;
}

export const tefillinRows = (rows: ReminderRow[]) => rows.filter((r) => r.title === TEFILLIN_TITLE);

/**
 * Дубли строк «הנחת תפילין» и «ראש חודש …» (фикс c695450 — по одной строке этих типов).
 * Другие типы не сверяем: две строки «פסח» (היום / מחר יעלה ויבוא) в חוה״מ — открытая находка, не требование.
 */
export const duplicateTitles = (rows: ReminderRow[]) =>
  rows
    .map((r) => r.title)
    .filter((t) => t === TEFILLIN_TITLE || t.startsWith('ראש חודש'))
    .filter((t, i, a) => a.indexOf(t) !== i);

/**
 * Открыть /home в подменённое время `fake` (момент с явным смещением, напр. '2026-10-04T10:00:00+03:00').
 * Ждёт ответ generate_reminders; если задан expectDay — проверяет p_day в запросе (подмена часов сработала).
 */
const warmed = new WeakSet<Page>();

export async function openHomeAt(page: Page, fake: string, opts: { expectDay?: string } = {}): Promise<ReminderRow[]> {
  const at = new Date(fake);
  if (!warmed.has(page)) {
    // первая подмена в контексте: свежий токен на реальном времени, затем часы и expires_at
    await setFixedTimeKeepingSession(page, at, '/profile');
    warmed.add(page);
  } else {
    // повторная подмена: часы уже фальшивые — только сдвинуть часы и expires_at копии токена на fake + 1 ч
    await page.clock.setFixedTime(at);
    await page.evaluate((exp) => {
      const k = Object.keys(localStorage).find((x) => /^sb-.+-auth-token$/.test(x));
      if (!k) throw new Error('Нет сессии Supabase в localStorage');
      const v = JSON.parse(localStorage.getItem(k) ?? 'null');
      v.expires_at = exp;
      localStorage.setItem(k, JSON.stringify(v));
    }, Math.floor(at.getTime() / 1000) + 3600);
  }
  const rpc = page.waitForResponse((r) => r.url().includes('/rpc/generate_reminders') && r.request().method() === 'POST', {
    timeout: 30_000,
  });
  await page.goto('/home');
  const resp = await rpc;
  expect(resp.ok(), `generate_reminders ответил ${resp.status()}`).toBe(true);
  if (opts.expectDay) {
    const body = JSON.parse(resp.request().postData() ?? '{}');
    expect(body.p_day, `p_day для ${fake}`).toBe(opts.expectDay);
  }
  return readReminders(page);
}

/**
 * Уборка после подмены часов: новый контекст из того же файла сессии, реальное время, /home →
 * generate_reminders пересоздаёт напоминания на сегодня. Файл сессии не меняется.
 */
export async function restoreTodayReminders(browser: Browser, testInfo: TestInfo, account = 'user1'): Promise<void> {
  const keys = ['baseURL', 'locale', 'viewport', 'userAgent', 'deviceScaleFactor', 'isMobile', 'hasTouch', 'timezoneId'] as const;
  const use = testInfo.project.use as Record<string, unknown>;
  const opts: BrowserContextOptions = {};
  for (const k of keys) if (use[k] !== undefined) (opts as Record<string, unknown>)[k] = use[k];
  const ctx = await browser.newContext({ ...opts, timezoneId: 'Asia/Jerusalem', storageState: path.resolve(__dirname, '../../../auth', `${account}.json`) });
  try {
    const page = await ctx.newPage();
    const rpc = page.waitForResponse((r) => r.url().includes('/rpc/generate_reminders'), { timeout: 30_000 }).catch(() => null);
    await page.goto('/home');
    await rpc;
    await readReminders(page).catch(() => []);
  } finally {
    await ctx.close();
  }
}
